/**
 * Build the DSH client bundle from the readable panel source.
 *
 * DSH dynamic client bundles are lazy CommonJS factories registered on the
 * page's module loader. The generated file is committed so an installed
 * tarball works without a build step; this script keeps source and output in
 * sync and is exercised by the package test.
 */

import { readFile, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SOURCE = join(ROOT, 'src', 'client-panel.js');
const OUTPUT = join(ROOT, 'src', 'client.js');
const HEADER = '// Generated by scripts/build-client.mjs from src/client-panel.js. Do not edit by hand.\n';

/**
 * @param {string} source panel factory body.
 * @returns {string} lazy-CJS module loader bundle.
 */
export function renderClient(source) {
  return `${HEADER}window.__ModuleLoader__.load({id:'@amadeus/persona',factory:(require)=>{\n${String(source).replace(/\s+$/, '')}\n}});\n`;
}

/**
 * Generate and write src/client.js.
 * @returns {Promise<string>} generated bundle.
 */
export async function buildClient() {
  const source = await readFile(SOURCE, 'utf8');
  const output = renderClient(source);
  await writeFile(OUTPUT, output, 'utf8');
  return output;
}

const invokedDirectly = process.argv[1] !== undefined
  && resolve(process.argv[1]) === resolve(fileURLToPath(import.meta.url));

if (invokedDirectly) {
  const output = await buildClient();
  process.stdout.write(`Wrote src/client.js (${Buffer.byteLength(output)} bytes).\n`);
}
